59|/*
60| * Malloc failure injection.
61| *
62| * To debug issues involving malloc failures, it's often helpful to set
63| * MALLOC_ABORT to 1. This should provide a backtrace of the failed
64| * allocation.
65| */
66|
67|#define XML_FUZZ_MALLOC_ABORT   0
