69|static void *
70|xmlFuzzMalloc(size_t size) {
71|    if (fuzzMaxAllocs > 0) {
72|        fuzzNumAllocs += 1;
73|        if (fuzzNumAllocs == fuzzMaxAllocs) {
74|#if XML_FUZZ_MALLOC_ABORT
75|            abort();
76|#endif
77|            fuzzAllocFailed = 1;
78|            return(NULL);
79|        }
80|    }
81|    return malloc(size);
82|}
