210| */
211|const char *
212|xmlFuzzReadRemaining(size_t *size) {
213|    const char *ret = fuzzData.ptr;
214|
215|    *size = fuzzData.remaining;
216|    fuzzData.ptr += fuzzData.remaining;
217|    fuzzData.remaining = 0;
218|
219|    return(ret);
220|}
