28|int
29|LLVMFuzzerTestOneInput(const char *data, size_t size) {
30|    xmlParserCtxtPtr ctxt;
31|    xmlDocPtr doc;
32|    xmlValidCtxtPtr vctxt;
33|    const char *docBuffer, *docUrl;
34|    size_t maxAlloc, docSize;
35|    int opts;
36|
37|    xmlFuzzDataInit(data, size);
38|    opts = (int) xmlFuzzReadInt(4);
39|    opts &= ~XML_PARSE_XINCLUDE;
40|    opts |= XML_PARSE_DTDVALID;
41|    maxAlloc = xmlFuzzReadInt(4) % (size + 100);
42|
43|    xmlFuzzReadEntities();
44|    docBuffer = xmlFuzzMainEntity(&docSize);
45|    docUrl = xmlFuzzMainUrl();
46|    if (docBuffer == NULL)
47|        goto exit;
48|
49|    /* Pull parser */
50|
51|    xmlFuzzMemSetLimit(maxAlloc);
52|    ctxt = xmlNewParserCtxt();
53|    if (ctxt != NULL) {
54|        doc = xmlCtxtReadMemory(ctxt, docBuffer, docSize, docUrl, NULL, opts);
55|        xmlFuzzCheckMallocFailure("xmlCtxtReadMemory",
56|                                  ctxt->errNo == XML_ERR_NO_MEMORY);
57|        xmlFreeDoc(doc);
58|        xmlFreeParserCtxt(ctxt);
59|    }
60|
61|    /* Post validation */
62|
63|    xmlFuzzMemSetLimit(maxAlloc);
64|    doc = xmlReadMemory(docBuffer, docSize, docUrl, NULL,
65|                        opts & ~XML_PARSE_DTDVALID);
66|    vctxt = xmlNewValidCtxt();
67|    xmlValidateDocument(vctxt, doc);
