218|/**
219| * xmlXIncludeNewRef:
220| * @ctxt: the XInclude context
221| * @URI:  the resource URI
222| * @elem:  the xi:include element
223| *
224| * Creates a new reference within an XInclude context
225| *
226| * Returns the new set
227| */
228|static xmlXIncludeRefPtr
229|xmlXIncludeNewRef(xmlXIncludeCtxtPtr ctxt, const xmlChar *URI,
230|	          xmlNodePtr elem) {
231|    xmlXIncludeRefPtr ret;
232|
233|    ret = (xmlXIncludeRefPtr) xmlMalloc(sizeof(xmlXIncludeRef));
234|    if (ret == NULL) {
235|        xmlXIncludeErrMemory(ctxt);
236|	return(NULL);
237|    }
238|    memset(ret, 0, sizeof(xmlXIncludeRef));
239|    if (URI == NULL) {
240|	ret->URI = NULL;
241|    } else {
242|	ret->URI = xmlStrdup(URI);
243|        if (ret->URI == NULL) {
244|            xmlXIncludeErrMemory(ctxt);
245|            xmlXIncludeFreeRef(ret);
246|            return(NULL);
247|        }
248|    }
249|    ret->fragment = NULL;
250|    ret->elem = elem;
251|    ret->xml = 0;
252|    ret->inc = NULL;
253|    if (ctxt->incNr >= ctxt->incMax) {
254|        xmlXIncludeRefPtr *tmp;
255|#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
256|        size_t newSize = ctxt->incMax ? ctxt->incMax * 2 : 1;
257|#else
258|        size_t newSize = ctxt->incMax ? ctxt->incMax * 2 : 4;
259|#endif
260|
261|        tmp = (xmlXIncludeRefPtr *) xmlRealloc(ctxt->incTab,
262|	             newSize * sizeof(ctxt->incTab[0]));
263|        if (tmp == NULL) {
264|	    xmlXIncludeErrMemory(ctxt);
265|	    xmlXIncludeFreeRef(ret);
266|	    return(NULL);
267|	}
268|        ctxt->incTab = tmp;
269|        ctxt->incMax = newSize;
270|    }
271|    ctxt->incTab[ctxt->incNr++] = ret;
272|    return(ret);
