397| */
398|static xmlDocPtr
399|xmlXIncludeParseFile(xmlXIncludeCtxtPtr ctxt, const char *URL) {
400|    xmlDocPtr ret = NULL;
401|    xmlParserCtxtPtr pctxt;
402|    xmlParserInputPtr inputStream;
403|
404|    xmlInitParser();
405|
406|    pctxt = xmlNewParserCtxt();
407|    if (pctxt == NULL) {
408|	xmlXIncludeErrMemory(ctxt);
409|	return(NULL);
410|    }
411|    if (ctxt->errorHandler != NULL)
412|        xmlCtxtSetErrorHandler(pctxt, ctxt->errorHandler, ctxt->errorCtxt);
413|
414|    /*
415|     * pass in the application data to the parser context.
416|     */
417|    pctxt->_private = ctxt->_private;
418|
419|    /*
420|     * try to ensure that new documents included are actually
421|     * built with the same dictionary as the including document.
422|     */
423|    if ((ctxt->doc != NULL) && (ctxt->doc->dict != NULL)) {
424|       if (pctxt->dict != NULL)
425|            xmlDictFree(pctxt->dict);
426|	pctxt->dict = ctxt->doc->dict;
427|	xmlDictReference(pctxt->dict);
428|    }
429|
430|    xmlCtxtUseOptions(pctxt, ctxt->parseFlags | XML_PARSE_DTDLOAD);
431|
432|    /* Don't read from stdin. */
433|    if ((URL != NULL) && (strcmp(URL, "-") == 0))
434|        URL = "./-";
435|
436|    inputStream = xmlLoadExternalEntity(URL, NULL, pctxt);
437|    if (inputStream == NULL)
438|        goto error;
439|
440|    inputPush(pctxt, inputStream);
441|
442|    if (pctxt->directory == NULL) {
443|        pctxt->directory = xmlParserGetDirectory(URL);
444|        if (pctxt->directory == NULL) {
445|            xmlXIncludeErrMemory(ctxt);
446|            goto error;
447|        }
448|    }
449|
450|    pctxt->loadsubset |= XML_DETECT_IDS;
451|
452|    xmlParseDocument(pctxt);
453|
454|    if (pctxt->wellFormed) {
455|        ret = pctxt->myDoc;
456|    }
457|    else {
458|        ret = NULL;
459|	if (pctxt->myDoc != NULL)
460|	    xmlFreeDoc(pctxt->myDoc);
461|        pctxt->myDoc = NULL;
462|    }
