627|/**
628| * xmlXIncludeCopyNode:
629| * @ctxt:  the XInclude context
630| * @elem:  the element
631| * @copyChildren:  copy children instead of node if true
632| *
633| * Make a copy of the node while expanding nested XIncludes.
634| *
635| * Returns a node list, not a single node.
636| */
637|static xmlNodePtr
638|xmlXIncludeCopyNode(xmlXIncludeCtxtPtr ctxt, xmlNodePtr elem,
639|                    int copyChildren) {
640|    xmlNodePtr result = NULL;
641|    xmlNodePtr insertParent = NULL;
642|    xmlNodePtr insertLast = NULL;
643|    xmlNodePtr cur;
644|
645|    if (copyChildren) {
646|        cur = elem->children;
647|        if (cur == NULL)
648|            return(NULL);
649|    } else {
650|        cur = elem;
651|    }
652|
653|    while (1) {
654|        xmlNodePtr copy = NULL;
655|        int recurse = 0;
656|
657|        if ((cur->type == XML_DOCUMENT_NODE) ||
658|            (cur->type == XML_DTD_NODE)) {
659|            ;
660|        } else if ((cur->type == XML_ELEMENT_NODE) &&
661|                   (cur->ns != NULL) &&
662|                   (xmlStrEqual(cur->name, XINCLUDE_NODE)) &&
663|                   ((xmlStrEqual(cur->ns->href, XINCLUDE_NS)) ||
664|                    (xmlStrEqual(cur->ns->href, XINCLUDE_OLD_NS)))) {
665|            xmlXIncludeRefPtr ref = xmlXIncludeExpandNode(ctxt, cur);
666|
667|            if (ref == NULL)
668|                goto error;
669|            /*
670|             * TODO: Insert XML_XINCLUDE_START and XML_XINCLUDE_END nodes
671|             */
672|            if (ref->inc != NULL) {
673|                copy = xmlStaticCopyNodeList(ref->inc, ctxt->doc,
674|                                             insertParent);
675|                if (copy == NULL) {
676|                    xmlXIncludeErrMemory(ctxt);
677|                    goto error;
678|                }
679|            }
680|        } else {
681|            copy = xmlStaticCopyNode(cur, ctxt->doc, insertParent, 2);
682|            if (copy == NULL) {
683|                xmlXIncludeErrMemory(ctxt);
684|                goto error;
685|            }
686|
687|            recurse = (cur->type != XML_ENTITY_REF_NODE) &&
688|                      (cur->children != NULL);
689|        }
690|
691|        if (copy != NULL) {
692|            if (result == NULL)
693|                result = copy;
694|            if (insertLast != NULL) {
695|                insertLast->next = copy;
696|                copy->prev = insertLast;
697|            } else if (insertParent != NULL) {
698|                insertParent->children = copy;
699|            }
700|            insertLast = copy;
701|            while (insertLast->next != NULL) {
702|                insertLast = insertLast->next;
703|            }
704|        }
705|
706|        if (recurse) {
707|            cur = cur->children;
708|            insertParent = insertLast;
709|            insertLast = NULL;
710|            continue;
711|        }
712|
713|        if (cur == elem)
714|            return(result);
715|
716|        while (cur->next == NULL) {
717|            if (insertParent != NULL)
718|                insertParent->last = insertLast;
719|            cur = cur->parent;
720|            if (cur == elem)
721|                return(result);
722|            insertLast = insertParent;
723|            insertParent = insertParent->parent;
724|        }
725|
726|        cur = cur->next;
727|    }
728|
729|error:
730|    xmlFreeNodeList(result);
731|    return(NULL);
