763|/**
764| * xmlXIncludeCopyRange:
765| * @ctxt:  the XInclude context
766| * @obj:  the XPointer result from the evaluation.
767| *
768| * Build a node list tree copy of the XPointer result.
769| *
770| * Returns an xmlNodePtr list or NULL.
771| *         The caller has to free the node tree.
772| */
773|static xmlNodePtr
774|xmlXIncludeCopyRange(xmlXIncludeCtxtPtr ctxt, xmlXPathObjectPtr range) {
775|    /* pointers to generated nodes */
776|    xmlNodePtr list = NULL, last = NULL, listParent = NULL;
777|    xmlNodePtr tmp, tmp2;
778|    /* pointers to traversal nodes */
779|    xmlNodePtr start, cur, end;
780|    int index1, index2;
781|    int level = 0, lastLevel = 0, endLevel = 0, endFlag = 0;
782|
783|    if ((ctxt == NULL) || (range == NULL))
784|	return(NULL);
785|    if (range->type != XPATH_RANGE)
786|	return(NULL);
787|    start = (xmlNodePtr) range->user;
788|
789|    if ((start == NULL) || (start->type == XML_NAMESPACE_DECL))
790|	return(NULL);
791|    end = range->user2;
792|    if (end == NULL)
793|	return(xmlDocCopyNode(start, ctxt->doc, 1));
794|    if (end->type == XML_NAMESPACE_DECL)
795|        return(NULL);
796|
797|    cur = start;
798|    index1 = range->index;
799|    index2 = range->index2;
800|    /*
801|     * level is depth of the current node under consideration
802|     * list is the pointer to the root of the output tree
803|     * listParent is a pointer to the parent of output tree (within
804|       the included file) in case we need to add another level
805|     * last is a pointer to the last node added to the output tree
806|     * lastLevel is the depth of last (relative to the root)
807|     */
808|    while (cur != NULL) {
809|	/*
810|	 * Check if our output tree needs a parent
811|	 */
812|	if (level < 0) {
813|	    while (level < 0) {
814|	        /* copy must include namespaces and properties */
815|	        tmp2 = xmlDocCopyNode(listParent, ctxt->doc, 2);
816|	        xmlAddChild(tmp2, list);
817|	        list = tmp2;
818|	        listParent = listParent->parent;
819|	        level++;
820|	    }
821|	    last = list;
822|	    lastLevel = 0;
823|	}
824|	/*
825|	 * Check whether we need to change our insertion point
826|	 */
827|	while (level < lastLevel) {
828|	    last = last->parent;
829|	    lastLevel --;
830|	}
831|	if (cur == end) {	/* Are we at the end of the range? */
832|	    if (cur->type == XML_TEXT_NODE) {
833|		const xmlChar *content = cur->content;
834|		int len;
835|
836|		if (content == NULL) {
837|		    tmp = xmlNewDocTextLen(ctxt->doc, NULL, 0);
838|		} else {
839|		    len = index2;
840|		    if ((cur == start) && (index1 > 1)) {
841|			content += (index1 - 1);
842|			len -= (index1 - 1);
843|		    } else {
844|			len = index2;
845|		    }
846|		    tmp = xmlNewDocTextLen(ctxt->doc, content, len);
847|		}
848|		/* single sub text node selection */
849|		if (list == NULL)
850|		    return(tmp);
851|		/* prune and return full set */
852|		if (level == lastLevel)
853|		    xmlAddNextSibling(last, tmp);
854|		else
855|		    xmlAddChild(last, tmp);
856|		return(list);
857|	    } else {	/* ending node not a text node */
858|	        endLevel = level;	/* remember the level of the end node */
859|		endFlag = 1;
860|		/* last node - need to take care of properties + namespaces */
861|		tmp = xmlDocCopyNode(cur, ctxt->doc, 2);
862|		if (list == NULL) {
863|		    list = tmp;
864|		    listParent = cur->parent;
865|		    last = tmp;
866|		} else {
867|		    if (level == lastLevel)
868|			last = xmlAddNextSibling(last, tmp);
869|		    else {
870|			last = xmlAddChild(last, tmp);
871|			lastLevel = level;
872|		    }
873|		}
874|
875|		if (index2 > 1) {
876|		    end = xmlXIncludeGetNthChild(cur, index2 - 1);
877|		    index2 = 0;
878|		}
879|		if ((cur == start) && (index1 > 1)) {
880|		    cur = xmlXIncludeGetNthChild(cur, index1 - 1);
881|		    index1 = 0;
882|		}  else {
883|		    cur = cur->children;
884|		}
885|		level++;	/* increment level to show change */
886|		/*
887|		 * Now gather the remaining nodes from cur to end
888|		 */
889|		continue;	/* while */
890|	    }
891|	} else if (cur == start) {	/* Not at the end, are we at start? */
892|	    if ((cur->type == XML_TEXT_NODE) ||
893|		(cur->type == XML_CDATA_SECTION_NODE)) {
894|		const xmlChar *content = cur->content;
895|
896|		if (content == NULL) {
897|		    tmp = xmlNewDocTextLen(ctxt->doc, NULL, 0);
898|		} else {
899|		    if (index1 > 1) {
900|			content += (index1 - 1);
901|			index1 = 0;
902|		    }
903|		    tmp = xmlNewDocText(ctxt->doc, content);
904|		}
905|		last = list = tmp;
906|		listParent = cur->parent;
907|	    } else {		/* Not text node */
908|	        /*
909|		 * start of the range - need to take care of
910|		 * properties and namespaces
911|		 */
912|		tmp = xmlDocCopyNode(cur, ctxt->doc, 2);
913|		list = last = tmp;
914|		listParent = cur->parent;
915|		if (index1 > 1) {	/* Do we need to position? */
916|		    cur = xmlXIncludeGetNthChild(cur, index1 - 1);
917|		    level = lastLevel = 1;
918|		    index1 = 0;
919|		    /*
920|		     * Now gather the remaining nodes from cur to end
921|		     */
922|		    continue; /* while */
923|		}
924|	    }
925|	} else {
926|	    tmp = NULL;
927|	    switch (cur->type) {
928|		case XML_DTD_NODE:
929|		case XML_ELEMENT_DECL:
930|		case XML_ATTRIBUTE_DECL:
931|		case XML_ENTITY_NODE:
932|		    /* Do not copy DTD information */
933|		    break;
934|		case XML_ENTITY_DECL:
935|		    /* handle crossing entities -> stack needed */
936|		    break;
937|		case XML_XINCLUDE_START:
938|		case XML_XINCLUDE_END:
939|		    /* don't consider it part of the tree content */
940|		    break;
941|		case XML_ATTRIBUTE_NODE:
942|		    /* Humm, should not happen ! */
943|		    break;
944|		default:
945|		    /*
946|		     * Middle of the range - need to take care of
947|		     * properties and namespaces
948|		     */
949|		    tmp = xmlDocCopyNode(cur, ctxt->doc, 2);
950|		    break;
951|	    }
952|	    if (tmp != NULL) {
953|		if (level == lastLevel)
954|		    last = xmlAddNextSibling(last, tmp);
955|		else {
956|		    last = xmlAddChild(last, tmp);
957|		    lastLevel = level;
958|		}
959|	    }
960|	}
961|	/*
962|	 * Skip to next node in document order
963|	 */
964|	cur = xmlXPtrAdvanceNode(cur, &level);
965|	if (endFlag && (level >= endLevel))
966|	    break;
967|    }
968|    return(list);
969|}
